def log_detailed_error(
    module: str,
    exc: Exception,
    reference: str = "",
    update_id: int = 0,
    event_type: str = "",
    callback_data: str = "",
    user_id: int = 0,
    state_name: str = "",
    recovered: bool = False,
):
    exc_type=type(exc).__name__
    tb="".join(traceback.format_exception(type(exc), exc, exc.__traceback__))[-4000:]

    conn=db()
    try:
        conn.execute(
            """INSERT INTO system_errors(
                module,severity,reference,error_text,recovered,created_at,
                update_id,event_type,callback_data,user_id,state_name,
                exception_type,traceback_text
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                module[:60],
                "error",
                reference[:250],
                str(exc)[:1500],
                1 if recovered else 0,
                datetime.now().isoformat(timespec="seconds"),
                int(update_id or 0),
                event_type[:80],
                callback_data[:500],
                int(user_id or 0),
                state_name[:200],
                exc_type[:120],
                tb,
            )
        )
        conn.commit()
    finally:
        conn.close()


